import type { NextConfig } from "next";

// All data comes from the real FastAPI backend. Requests to /api/* are proxied, so the browser needs no CORS
// and no backend URL. Documents never leave the machine.
const BACKEND = process.env.HAL_BACKEND_URL ?? "http://127.0.0.1:8000";

const nextConfig: NextConfig = {
  // Tailwind v4 is compiled through this Turbopack rule (as generated by create-next-app).
  turbopack: {
    rules: {
      "*.css": { loaders: ["@tailwindcss/turbopack"], as: "*.css" },
    },
  },
  async rewrites() {
    return [{ source: "/api/:path*", destination: `${BACKEND}/api/:path*` }];
  },
};

export default nextConfig;
